const events={hit:'受到直接攻击后',shieldHit:'护盾承受直接攻击后',shieldBreak:'护盾被击破后',magicHit:'受到法术直接攻击后',arts:'使用ABC后',supportArts:'使用非攻击ABC后',attack:'完成攻击动作后',nonAttack:'完成非攻击动作后',rest:'休整后',defend:'防御后',martial:'使用体术后',start:'自身机会开始时',anyAction:'行动结束后',dodge:'闪避成功后',death:'实际死亡时',kill:'击杀时',gaugeGain:'行动条因技能增加后',gaugeLoss:'行动条因技能减少后',heal:'获得治疗后',shield:'获得护盾后',stealth:'尝试隐匿时'};
const targets={self:'自身',target:'目标',ally:'所选友方',allies:'己方全体',pets:'自己的召唤物',holder:'状态持有者',source:'施法者',enemySource:'攻击者'};
const buffs={A:'体术强度',P:'术强',V:'速度',mitigation:'直伤减免',magicMitigation:'法术直伤减免',defensePenalty:'双抗减伤率降低',defenseBonus:'双抗减伤率提高',healPenalty:'治疗量降低',shieldPenalty:'获得护盾量降低',gaugePenalty:'技能加条量降低',gaugeProtection:'技能扣条量降低',ignoreDefense:'攻击忽略减伤率',dotBonus:'毒系数追加',discount:'技能基础费用降低',restPenalty:'休整回能降低',dotEnergy:'灼烧伤害回复E'};
function testText(t){return Object.entries(t).map(([k,v])=>({status:'目标有'+v,selfStatus:'自身有'+v,anyStatus:'目标有'+(Array.isArray(v)?v.join('/') :v),consumed:'消耗至少'+v+'层',resource:'资源至少'+v,resourceBefore:'施放前资源至少'+v,mode:'分支为第'+(Number(v)+1)+'项',ownPet:'自己的召唤物存活',lastAction:'上次动作是'+({martial:'体术',rest:'休整',defend:'防御'}[v]||v),targetHpBelow:'目标HP低于'+Number(v)*100+'%',selfHpBelow:'自身HP低于'+Number(v)*100+'%',energyRatioBelow:'目标E低于容量'+Number(v)*100+'%',energyBelow:'目标E不高于'+v,gaugeBelow:'目标行动条不高于'+v,armorHigher:'目标物防≥魔抗',targetOwner:'目标是召唤物',targetDead:'目标已死亡',eventAttack:'触发动作是攻击',unhurt:'上次自身行动后未受直接伤害',shieldBroken:'自身护盾曾被击破',recorded:'命中记录目标',alone:'己方无其他存活主体'}[k]||k)).join('且');}
export function describeEffect(o,describe){let tar=targets[o.to||'target'],sub=a=>a.map(describe).join('；');switch(o.op){
 case'if':return `若${testText(o.test)}：${sub(o.effects)}${o.otherwise.length?'；否则：'+sub(o.otherwise):''}`;
 case'mark':return `${tar}获得${o.n}层【${o.name}】，上限${o.cap||3}，${o.duration>=99?'本场持续':o.duration+'次机会'}${o.name==='麻痹'?'；到2层清空标记并清空全部行动条':o.name==='神经积累'?'；到3层清空，80%P真伤与沉默1机会':''}`;
 case'remove':return `移除${tar}的${o.name}`;
 case'extend':return `${tar}已有${o.name}剩余时间设为${o.duration}次机会`;
 case'consumeMark':return `消耗目标全部${o.name}，作为本招消耗层数`;
 case'buff':return `${tar}获得${o.name}（${Object.entries(o.values).map(([k,v])=>k==='dodge'?'下次直接伤害闪避1段':k==='survive'?'敌方首次致命伤保留1HP':k==='martialTrue'?'体术改为真实伤害':k==='noEnergy'?'自然与休整不回E':k==='noAttack'?'只可休整与防御':k==='antiStealth'?'敌方无法新获隐匿':`${buffs[k]||k} ${['discount','restPenalty','dotEnergy'].includes(k)?v+'E':Math.round(v*100)+'%'}`).join('、')}），${o.duration>=99?'本场':o.duration+'次机会'}`;
 case'watch':return `${tar}获得${o.name}，${o.duration>=99?'本场':o.duration+'次机会'}内${events[o.event]}：${sub(o.effects)}；${o.repeat?'每动作最多1次'+(o.max?'，合计至多'+o.max+'次':''):'触发1次后移除'}；反应伤害不再触发反应`;
 case'rearm':return `把${o.name}改为${events[o.event]}触发：${sub(o.effects)}`;
 case'mode':return o.n==='toggle'?'切换第1/2分支':o.n==='cycle3'?'按1→2→3→1循环分支':'切到第'+(o.n+1)+'分支';
 case'resourceSet':return `专属资源设为${o.n}，受上限限制`;
 case'cycleResource':return `专属资源+${o.n}，按1至上限循环`;
 case'resourceHeal':return `${tar}恢复消耗层数×${o.ratio*100}%其H`;
 case'resourceShield':return `${tar}获得(${o.ratio*100}+${o.per*100}×消耗层数)%H盾`;
 case'resourceEnergy':return `${tar}回复消耗层数×${o.n}E`;
 case'resourceLife':return `每消耗1层支付${o.ratio*100}%自身H，不能致死`;
 case'percentHit':return `追加目标${o.current?'当前':'最大'}HP×${o.ratio*100}%${o.type==='true'?'真':'法'}伤，上限${o.cap*100}%P${o.limit?'，每目标本场至多'+o.limit+'次':''}`;
 case'targetDelayed':return `目标下次机会开始：${sub(o.effects)}`;
 case'purge':return '移除目标最早1个临时属性增幅';
 case'reset':return `重置自身${o.button}冷却`;
 case'cooldown':return `敌方C冷却延长，最多封锁1次自身机会，每敌本场最多${o.max}次`;
 case'chain':return `另一个带${o.name}的敌人受到${o.coef*100}%P法伤；清除这些${o.name}`;
 case'detonate':return `引爆全部敌方${o.name}，各造成${o.coef*100}%${o.basis}${o.type==='physical'?'物':'法'}伤并清除标记`;
 case'burst':return `其他敌人各受${o.coef*100}%P法伤${o.status?'并获得'+o.status:''}`;
 case'dotBurst':return `立即结算目标${o.name}1跳${o.keep?'，保留状态':'后清除状态'}`;
 case'shieldLaunch':return `移除${o.from==='target'?'目标':'自身'}全部护盾，追加盾值×${o.ratio*100}%${o.type==='true'?'真':'法'}伤，上限${o.cap*100}%${o.basis}${o.from==='target'?'；移除盾值×50%转为自身盾，上限12%H':''}`;
 case'transferShield':return `移除自身全部盾，将其中50%转给另一友方，上限${o.ratio*100}%其H；仅自己时改回复10E`;
 case'allyConsume':return `己方有${o.name}时，移除1份并${sub(o.effects)}`;
 case'secondary':return `另一存活敌人：${sub(o.effects)}${o.fallback?'；没有其他敌人：'+sub(o.fallback):''}`;
 case'focusGain':return '记录目标并获得1资源，换目标则先清空旧资源';
 case'focusSet':return `记录目标，资源设为${o.n}`;
 case'returnBlade':return '旧记录目标存活且不同时，先对其造成40%A物伤；重记本目标';
 case'snapshot':return '记录当前HP与E，保留2次自身机会';
 case'recall':return `${tar}按快照恢复生命，上限${o.h*100}%H，较低快照不扣血${o.e?'；自身E至快照值，最多恢复'+o.e+'E':''}；用后删除快照`;
 case'snapshotTeam':return `记录己方HP，${o.delay}次自身机会后恢复至记录值，每人至多25%H，不复活`;
 case'swapGauge':return '交换自身与目标当前行动条，范围0—95';
 case'balanceHP':return '存活己方主体HP总量不增加，按各自H比例重新分配，至少1HP';
 case'transferNegative':return `将自己最多${o.count}种可净化负面状态转给敌人，保留剩余时间`;
 case'takeNegative':return `将友方最多${o.count}种可净化负面状态转给自己，保留剩余时间`;
 case'randomNegative':return `从毒、灼烧、破防、破魔、迟缓、衰弱、脆弱中无放回抽取${o.count}种，各施加1层、${o.duration}目标机会；各目标独立抽取，相同种类遵循原叠层规则`;
 case'spread':return `将主目标最多${o.count}种非硬控负面状态复制给另一敌人，保留剩余时间`;
 case'cleanseGain':return '净化自身负面，每清除1种获得1资源';
 case'pushDamage':return `扣目标60行动条；每点实际扣除追加${o.coef*100}%P真伤`;
 case'pushRefund':return `尝试扣60行动条；每点触底损失返还${o.n}E，最多24E`;
 case'markHarvest':return `清除全场${o.name}，每份治疗自己${o.ratio*100}%H，上限${o.cap*100}%H；没有标记支付5%H`;
 case'poisonHarvest':return '清除目标全部毒，每层为己方全体治疗5%各自H';
 case'energyHarvest':return `扣目标至多${o.n}E，实际扣除量转为自身资源`;
 case'steal':return `非领袖目标被夺取至多${o.energy}E与${o.ratio*100}%当前HP，后者上限自身${o.cap*100}%H，用于治疗自己`;
 case'hpCap':return `自身HP裁至最多${o.ratio*100}%H`;
 case'debt':return `记录${o.ratio*100}%H延迟伤账，上限25%H，2自身机会后支付`;
 case'payDebt':return `立即支付伤账×${o.ratio*100}%并清除全部伤账`;
 case'changeForm':return '拟形蛮力→咒术→坚躯循环，撤销旧倍率后使A/P/H之一×1.30，HP同比变化；碎片攻击更新为70%Q真伤';
 case'dreamDragon':return '召唤梦龙（28%H、85%P法伤、双抗100%、4主人机会、上限2）；已有2只时融合为大梦龙（生命为剩余HP总和、200%P法伤、3机会）';
 case'pet':return {remove:'移除自己最早1只召唤物',heal:`自己的召唤物恢复${o.ratio*100}%各自H`,extend:`召唤物寿命${o.duration>0?'+':''}${o.duration}，每只仅1次`,refresh:`召唤物寿命重设${o.duration}，每只仅1次`,payLife:`自己的召唤物各损失${o.ratio*100}%各自H`,convertHeal:`移除最早召唤物，以其剩余HP×${o.ratio*100}%治疗自己，上限${o.cap*100}%自身H`,convertShield:`移除最早召唤物，把剩余HP×${o.ratio*100}%转给${tar}为盾，上限${o.cap*100}%其H`,volley:`每只召唤物立即追加${o.coef*100}%P法伤`,explode:`回收全部自己召唤物，每只对敌全体${o.coef*100}%P法伤并回复${o.energy}E`,observe:`自己的召唤物攻击改0，每主人结束给所选友方${o.energy||0}E及${(o.shield||0)*100}%H盾`,splitDragon:'将大梦龙等分剩余生命拆为2梦龙，攻击90%P法伤，寿命沿用；没有大龙则令现存龙立即攻击'}[o.task];
 default:return null;}}
